  "claims": [
    {
      "claim": "L1/L2 nucleoside analog absolute oral bioavailability values are consistently at or above the 20% threshold: zalcitabine 80% in fasted HIV patients (C15) and 30% in fasted mice (C39); ddA/ddI 38±15% in fasting patients (C12) with additional dog/mouse absolute F values of 93%, 50%, 47%, 46%, 38% and ddI 30–54% (C26, C36, C40, C41, C50, C52); OGT719 about 25% in patients (C10).",
      "card_ids": ["C15", "C39", "C12", "C26", "C36", "C40", "C41", "C50", "C52", "C10"]
    },
    {
      "claim": "L3 oral exposure records for guanine/carbocyclic nucleoside analogs show measurable oral absorption: penciclovir after oral famciclovir reached Cmax 3.45 µg/mL and AUC0-∞ 8.94 µg·h/mL (C82, C72); entecavir reached Tmax 0.63–1.0 h after oral dosing (C61, C84); decitabine oral/IV 5-day AUClast ratio was 97.6% with cedazuridine (C89).",
      "card_ids": ["C82", "C72", "C61", "C84", "C89"]
    },
    {
      "claim": "No L3 record provides affirmative evidence of F<20% for the query; Tmax-only records are neutral on extent, and non-nucleoside records such as tedizolid (C74) are not transferable to this guanine carbocyclic nucleoside.",
      "card_ids": ["C74"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
