      ]
    },
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "low",
      "direction": "supportive",
      "decision_effect": "no_change",
      "card_ids": [
        "C100", "C60", "C76", "C94", "C97", "C67", "C77", "C78", "C93",
        "C66", "C68", "C104", "C74"
      ]
    }
  ],
  "evidence_gaps": [
    "No direct measured absolute oral bioavailability for the exact query molecule.",
    "No human pharmacokinetic data for the specific cyclobutyl guanine nucleoside scaffold.",
    "L3 records are exposure metrics (AUC, Cmax, Tmax) rather than absolute F; they do not quantify the fraction absorbed for the query.",
    "Potential metabolic liability (e.g., deamination or phosphorylation-dependent activation) and transporter involvement are not experimentally characterized for the query.",
    "Formulation and dose for the query are not specified beyond the fasted condition."
  ],
  "decision_summary": "L3 oral exposure records for nucleoside analogs (entecavir, famciclovir/penciclovir, decitabine, lamivudine, tenofovir) show measurable-to-high oral exposure and rapid absorption; none provide affirmative evidence of F<20% for the query. Combined with L1/L2 nucleoside analog absolute F values ≥20%, prediction remains high with moderate confidence."
}

